const r = items[0].json;
const taxaBounce = r.taxa_bounce != null ? parseFloat(r.taxa_bounce) : 0;
const taxaReclamacao = r.taxa_reclamacao != null ? parseFloat(r.taxa_reclamacao) : 0;
const disparar = taxaBounce > 0.05 || taxaReclamacao > 0.003;
return [{
  json: {
    disparar, taxaBounce, taxaReclamacao,
    campanha_id: $('Parâmetros').first().json.campanha_id,
  },
}];

