UPDATE campanhas SET pausada = true,
  motivo_pausa = 'Circuit breaker: bounce=' || $2::text || ' reclamacao=' || $3::text || ' em ' || now()::text
WHERE id = $1 AND $4::boolean = true AND pausada = false;
